		"auto_str_65":"Redémarrer le serveur en mode sécurisé",
		"auto_str_66":"<div class='bt-form bt-window-restart'> <div class='pd15'> <p style='color:red; margin-bottom:10px; font-size:15px;'>Attention : si votre serveur est un conteneur, veuillez annuler. </p> <div class='SafeRestart' style='line-height:26px'> <p>Le redémarrage sécurisé permet de garantir la sécurité des fichiers. Les opérations suivantes seront effectuées :</p> <p>1. Arrêt du service Web</p> <p>2. Arrêt du service MySQL</p> <p>3. Lancement du redémarrage du serveur</p> <p>4. Attente du démarrage du serveur</p> </div> </div> <div class='bt-form-submit-btn' > <button type='button' class='btn btn-danger btn-sm btn-reboot'>Annuler</button> <button type='button' class='btn btn-success btn-sm WSafeRestart' >Confirmer</button> </div> </div>",
