		"auto_str_119":"Échec de la récupération des informations système : ",
		"auto_str_120":"AES : détermine si les opérations de chiffrement et de déchiffrement des protocoles HTTPS, SSH, etc. bénéficient d'une accélération matérielle.",
		"auto_str_121":"VMX : détermine si le serveur prend en charge la virtualisation au niveau matériel (s'il est possible de lancer des machines virtuelles).",
