		"config_auto_str_45":"<div class='bt-form'>\t\t\t\t<div class='line'>\t\t\t\t\t<span class='tname'>Mot de passe</span>\ t\t\t\t\t<div class='info-r'><input class='bt-input-text' type='text' name='password1' id='p1' value='' placeholder='Nouveau mot de passe' style='width:70%'/ ></div>\t\t\t\t</div>\t\t\t\t<div class='line'>\t\t\t\t\t<span class='tname'>Confirmer </span>\ t\t\t\t\t<div class='info-r'><input class='bt-input-text' type='text' name='password2' id='p2' value='' placeholder='Entrez-le à nouveau' style='width:70%' /></div>\ t\t\t\t</div>\t\t\t</div>",
