		"config_auto_str_53":"Au hasard",
		"config_auto_str_54":"<div class='bt-form pd20'>\t\t\t<div class='line'><span class='tname'>Nom d'utilisateur</span>\ t\t\t\t<div class='info-r'><input class='bt-input-text' type='text' name='password1' id='p1' value='' placeholder='Nouveau nom d'utilisateur' style='width:70%'/ ></div>\t\t\t</div>\t\t\t<div class='line'>\t\t\t\t<span class='tname'>Confirmez </span>\ t\t\t\t<div class='info-r'><input class='bt-input-text' type='text' name='password2' id='p2' value='' placeholder='Entrez-le à nouveau' style='width:70%'/ ></div>\t\t\t</div>\t\t</div>",
		"config_auto_str_55":"Le nom d'utilisateur doit comporter au moins 3 caractères.",
