		"config_auto_str_62":"<div class='bt-form pd20'>\t\t\t<div class='line'>\t\t\t\t<span class='tname'>Fuseau horaire</span>\ t\t\t\t<div class='info-r'>\t\t\t\t\t<select class='bt-input-text mr5' name='timezone' style='width: 250px;' ></select>\t\t\t\t</div>\t\t\t</div>\t\t</div>",
