		"config_auto_str_134":"<li>Collez le contenu de vos fichiers *.key et *.pem, puis enregistrez. </li>\t\t\t\t\t\t\t\t\t<li>Si le navigateur indique que la chaîne de certificats est incomplète, vérifiez que les certificats au format PEM ont bien été concaténés correctement</li><li>Certificat au format PEM = certificat de domaine.crt + certificat racine (root_bundle).crt</li>",
