		"config_auto_str_151":"Voulez-vous vraiment supprimer le certificat SSL auto-signé local ?",
		"config_auto_str_152":"Avertissement : la suppression du certificat gratuit de 90 jours désactivera le SSL du panneau de contrôle et entraînera son redémarrage automatique. Vous devrez alors revenir au protocole HTTP pour y accéder ! Êtes-vous sûr de vouloir continuer ?",
		"config_auto_str_153":"Remarque",
		"config_auto_str_154":"Confirmer",
		"config_auto_str_155":"Annuler",
		"config_auto_str_156":"Suppression du certificat et redémarrage du panneau de contrôle en cours...",
		"config_auto_str_157":"Gestion des autorisations temporaires",
		"config_auto_str_158":"<div class='pd20'>\t\t\t\t\t<button class='btn btn-success btn-sm refresh_log'>Actualiser le journal</button>\t\t\t\t\t<div class='divtable mt10'>\ t\t\t\t\t\t<table class='table table-hover'>\t\t\t\t\t\t\t<thead>\t\t\t\t\ t\t\t\t<tr><th>Type d'opération</th><th>Heure de l'opération</th><th>Journal</th></tr>\t\t\t\t\t\t\t</thead>\t\t\t\ t\t\t\t<tbody id='logs_list'></tbody>\t\t\t\t\t\t</table>\t\t\t\t\t</div>\t\t\t\t</div>",
